def make_mut(sequences,wt):
	top_r = []
	for s in sequences:
		i = 1
		top = ''
		while i <= len(wt):
			if wt[i-1] != s[i-1]:
				if len(top)>0:
					top += ','
				top += wt[i-1]+'A'+str(i)+s[i-1]+','+wt[i-1]+'B'+str(i)+s[i-1]
			i+=1
		top += ';'
		top_r.append(top)
	return top_r


